7	import type { AgentCard, SecurityScheme } from '@a2a-js/sdk';
8	import type {
9	  A2AAuthConfig,
10	  A2AAuthProvider,
11	  AuthValidationResult,
12	} from './types.js';
13	import { ApiKeyAuthProvider } from './api-key-provider.js';
14	
15	export interface CreateAuthProviderOptions {
16	  /** Required for OAuth/OIDC token storage. */
17	  agentName?: string;
18	  authConfig?: A2AAuthConfig;
19	  agentCard?: AgentCard;
20	}
21	
22	/**
23	 * Factory for creating A2A authentication providers.
24	 * @see https://a2a-protocol.org/latest/specification/#451-securityscheme
25	 */
26	export class A2AAuthProviderFactory {
27	  static async create(
28	    options: CreateAuthProviderOptions,
29	  ): Promise<A2AAuthProvider | undefined> {
30	    const { agentName: _agentName, authConfig, agentCard } = options;
31	
32	    if (!authConfig) {
33	      if (
34	        agentCard?.securitySchemes &&
35	        Object.keys(agentCard.securitySchemes).length > 0
36	      ) {
37	        return undefined; // Caller should prompt user to configure auth
38	      }
39	      return undefined;
40	    }
41	
42	    switch (authConfig.type) {
43	      case 'google-credentials':
44	        // TODO: Implement
45	        throw new Error('google-credentials auth provider not yet implemented');
46	
47	      case 'apiKey': {
48	        const provider = new ApiKeyAuthProvider(authConfig);
49	        await provider.initialize();
50	        return provider;
51	      }
52	
53	      case 'http':
54	        // TODO: Implement
55	        throw new Error('http auth provider not yet implemented');
56	
57	      case 'oauth2':
58	        // TODO: Implement
59	        throw new Error('oauth2 auth provider not yet implemented');
60	
61	      case 'openIdConnect':
62	        // TODO: Implement
63	        throw new Error('openIdConnect auth provider not yet implemented');
64	
65	      default: {
66	        const _exhaustive: never = authConfig;
67	        throw new Error(
68	          `Unknown auth type: ${(_exhaustive as A2AAuthConfig).type}`,
69	        );
70	      }
71	    }
72	  }
73	
74	  /** Create provider directly from config, bypassing AgentCard validation. */
75	  static async createFromConfig(
76	    authConfig: A2AAuthConfig,
77	    agentName?: string,
78	  ): Promise<A2AAuthProvider> {
79	    const provider = await A2AAuthProviderFactory.create({
80	      authConfig,
81	      agentName,
82	    });
83	
84	    // create() returns undefined only when authConfig is missing.
85	    // Since authConfig is required here, provider will always be defined
86	    // (or create() throws for unimplemented types).
87	    return provider!;
88	  }
89	
90	  /** Validate auth config against AgentCard's security requirements. */
91	  static validateAuthConfig(
92	    authConfig: A2AAuthConfig | undefined,
93	    securitySchemes: Record<string, SecurityScheme> | undefined,
94	  ): AuthValidationResult {
95	    if (!securitySchemes || Object.keys(securitySchemes).length === 0) {
96	      return { valid: true };
97	    }
98	
99	    const requiredSchemes = Object.keys(securitySchemes);
100	
101	    if (!authConfig) {
102	      return {
103	        valid: false,
104	        diff: {
105	          requiredSchemes,
106	          configuredType: undefined,
107	          missingConfig: ['Authentication is required but not configured'],
108	        },
109	      };
110	    }
111	
112	    const matchResult = A2AAuthProviderFactory.findMatchingScheme(
113	      authConfig,
114	      securitySchemes,
115	    );
116	
117	    if (matchResult.matched) {
118	      return { valid: true };
119	    }
120	
121	    return {
122	      valid: false,
123	      diff: {
124	        requiredSchemes,
125	        configuredType: authConfig.type,
126	        missingConfig: matchResult.missingConfig,
127	      },
128	    };
129	  }
130	
131	  // Security schemes have OR semantics per A2A spec - matching any single scheme is sufficient
132	  private static findMatchingScheme(
133	    authConfig: A2AAuthConfig,
134	    securitySchemes: Record<string, SecurityScheme>,
135	  ): { matched: boolean; missingConfig: string[] } {
136	    const missingConfig: string[] = [];
137	
138	    for (const [schemeName, scheme] of Object.entries(securitySchemes)) {
139	      switch (scheme.type) {
140	        case 'apiKey':
141	          if (authConfig.type === 'apiKey') {
142	            return { matched: true, missingConfig: [] };
143	          }
144	          missingConfig.push(
145	            `Scheme '${schemeName}' requires apiKey authentication`,
146	          );
147	          break;
148	
149	        case 'http':
150	          if (authConfig.type === 'http') {
151	            if (
152	              authConfig.scheme.toLowerCase() === scheme.scheme.toLowerCase()
153	            ) {
154	              return { matched: true, missingConfig: [] };
155	            }
156	            missingConfig.push(
157	              `Scheme '${schemeName}' requires HTTP ${scheme.scheme} authentication, but ${authConfig.scheme} was configured`,
158	            );
159	          } else if (
160	            authConfig.type === 'google-credentials' &&
161	            scheme.scheme.toLowerCase() === 'bearer'
162	          ) {
163	            return { matched: true, missingConfig: [] };
164	          } else {
165	            missingConfig.push(
166	              `Scheme '${schemeName}' requires HTTP ${scheme.scheme} authentication`,
167	            );
168	          }
169	          break;
170	
171	        case 'oauth2':
172	          if (authConfig.type === 'oauth2') {
173	            return { matched: true, missingConfig: [] };
174	          }
175	          missingConfig.push(
176	            `Scheme '${schemeName}' requires OAuth 2.0 authentication`,
177	          );
178	          break;
179	
180	        case 'openIdConnect':
181	          if (authConfig.type === 'openIdConnect') {
182	            return { matched: true, missingConfig: [] };
183	          }
184	          missingConfig.push(
185	            `Scheme '${schemeName}' requires OpenID Connect authentication`,
186	          );
187	          break;
188	
189	        case 'mutualTLS':
190	          missingConfig.push(
191	            `Scheme '${schemeName}' requires mTLS authentication (not yet supported)`,
192	          );
193	          break;
194	
195	        default: {
196	          const _exhaustive: never = scheme;
197	          missingConfig.push(
198	            `Unknown security scheme type: ${(_exhaustive as SecurityScheme).type}`,
199	          );
200	        }
201	      }
202	    }
203	
204	    return { matched: false, missingConfig };
205	  }
206	
207	  /** Get human-readable description of required auth for error messages. */
208	  static describeRequiredAuth(
209	    securitySchemes: Record<string, SecurityScheme>,
210	  ): string {
211	    const descriptions: string[] = [];
212	
213	    for (const [name, scheme] of Object.entries(securitySchemes)) {
214	      switch (scheme.type) {
215	        case 'apiKey':
216	          descriptions.push(
217	            `API Key (${name}): Send ${scheme.name} in ${scheme.in}`,
218	          );
219	          break;
220	        case 'http':
221	          descriptions.push(`HTTP ${scheme.scheme} (${name})`);
222	          break;
223	        case 'oauth2':
224	          descriptions.push(`OAuth 2.0 (${name})`);
225	          break;
226	        case 'openIdConnect':
227	          descriptions.push(`OpenID Connect (${name})`);
228	          break;
229	        case 'mutualTLS':
230	          descriptions.push(`Mutual TLS (${name})`);
231	          break;
232	        default: {
233	          const _exhaustive: never = scheme;
234	          // This ensures TypeScript errors if a new SecurityScheme type is added
235	          descriptions.push(
236	            `Unknown (${name}): ${(_exhaustive as SecurityScheme).type}`,
237	          );
238	        }
239	      }
240	    }
