7	import { debugLogger } from '../../utils/debugLogger.js';
8	import { getShellConfiguration, spawnAsync } from '../../utils/shell-utils.js';
9	
10	const COMMAND_TIMEOUT_MS = 60_000;
11	
12	/**
13	 * Resolves a value that may be an environment variable reference,
14	 * a shell command, or a literal value.
15	 *
16	 * Supported formats:
17	 * - `$ENV_VAR`: Read from environment variable
18	 * - `!command`: Execute shell command and use output (trimmed)
19	 * - `$$` or `!!`: Escape prefix, returns rest as literal
20	 * - Any other string: Use as literal value
21	 *
22	 * @param value The value to resolve
23	 * @returns The resolved value
24	 * @throws Error if environment variable is not set or command fails
25	 */
26	export async function resolveAuthValue(value: string): Promise<string> {
27	  // Support escaping with double prefix (e.g. $$ or !!).
28	  // Strips one prefix char: $$FOO → $FOO, !!cmd → !cmd (literal, not resolved).
29	  if (value.startsWith('$$') || value.startsWith('!!')) {
30	    return value.slice(1);
31	  }
32	
33	  // Environment variable: $MY_VAR
34	  if (value.startsWith('$')) {
35	    const envVar = value.slice(1);
36	    const resolved = process.env[envVar];
37	    if (resolved === undefined || resolved === '') {
38	      throw new Error(
39	        `Environment variable '${envVar}' is not set or is empty. ` +
40	          `Please set it before using this agent.`,
41	      );
42	    }
43	    debugLogger.debug(`[AuthValueResolver] Resolved env var: ${envVar}`);
44	    return resolved;
45	  }
46	
47	  // Shell command: !command arg1 arg2
48	  if (value.startsWith('!')) {
49	    const command = value.slice(1).trim();
50	    if (!command) {
51	      throw new Error('Empty command in auth value. Expected format: !command');
52	    }
53	
54	    debugLogger.debug(`[AuthValueResolver] Executing command for auth value`);
55	
56	    const shellConfig = getShellConfiguration();
57	    try {
58	      const { stdout } = await spawnAsync(
59	        shellConfig.executable,
60	        [...shellConfig.argsPrefix, command],
61	        {
62	          signal: AbortSignal.timeout(COMMAND_TIMEOUT_MS),
63	          windowsHide: true,
64	        },
65	      );
66	
67	      const trimmed = stdout.trim();
68	      if (!trimmed) {
69	        throw new Error(`Command '${command}' returned empty output`);
70	      }
71	      return trimmed;
72	    } catch (error) {
73	      if (error instanceof Error && error.name === 'AbortError') {
74	        throw new Error(
75	          `Command '${command}' timed out after ${COMMAND_TIMEOUT_MS / 1000} seconds`,
76	        );
77	      }
78	      throw error;
79	    }
80	  }
81	
82	  // Literal value - return as-is
83	  return value;
84	}
85	
86	/**
87	 * Check if a value needs resolution (is an env var or command reference).
88	 */
89	export function needsResolution(value: string): boolean {
90	  return value.startsWith('$') || value.startsWith('!');
91	}
92	
93	/**
94	 * Mask a sensitive value for logging purposes.
95	 * Shows the first and last 2 characters with asterisks in between.
96	 */
97	export function maskSensitiveValue(value: string): string {
98	  if (value.length <= 12) {
99	    return '****';
100	  }
101	  return `${value.slice(0, 2)}****${value.slice(-2)}`;
102	}
