97	  .object({
98	    kind: z.literal('local').optional().default('local'),
99	    name: nameSchema,
100	    description: z.string().min(1),
101	    display_name: z.string().optional(),
102	    tools: z
103	      .array(
104	        z.string().refine((val) => isValidToolName(val), {
