106	        }),
107	      )
108	      .optional(),
109	    model: z.string().optional(),
110	    temperature: z.number().optional(),
111	    max_turns: z.number().int().positive().optional(),
112	    timeout_mins: z.number().int().positive().optional(),
113	  })
114	  .strict();
115	
116	/**
117	 * Base fields shared by all auth configs.
118	 */
119	const baseAuthFields = {
120	  agent_card_requires_auth: z.boolean().optional(),
121	};
122	
123	/**
124	 * API Key auth schema.
125	 * Supports sending key in header, query parameter, or cookie.
126	 */
127	const apiKeyAuthSchema = z.object({
128	  ...baseAuthFields,
129	  type: z.literal('apiKey'),
130	  key: z.string().min(1, 'API key is required'),
131	  name: z.string().optional(),
132	});
