134	/**
135	 * HTTP auth schema (Bearer or Basic).
136	 * Note: Validation for scheme-specific fields is applied in authConfigSchema
137	 * since discriminatedUnion doesn't support refined schemas directly.
138	 */
139	const httpAuthSchema = z.object({
140	  ...baseAuthFields,
141	  type: z.literal('http'),
142	  scheme: z.enum(['Bearer', 'Basic']),
143	  token: z.string().min(1).optional(),
144	  username: z.string().min(1).optional(),
145	  password: z.string().min(1).optional(),
146	});
147	
148	const authConfigSchema = z
149	  .discriminatedUnion('type', [apiKeyAuthSchema, httpAuthSchema])
150	  .superRefine((data, ctx) => {
151	    if (data.type === 'http') {
152	      if (data.scheme === 'Bearer' && !data.token) {
153	        ctx.addIssue({
154	          code: z.ZodIssueCode.custom,
155	          message: 'Bearer scheme requires "token"',
156	          path: ['token'],
157	        });
158	      }
159	      if (data.scheme === 'Basic') {
160	        if (!data.username) {
161	          ctx.addIssue({
162	            code: z.ZodIssueCode.custom,
163	            message: 'Basic authentication requires "username"',
164	            path: ['username'],
165	          });
166	        }
167	        if (!data.password) {
168	          ctx.addIssue({
169	            code: z.ZodIssueCode.custom,
170	            message: 'Basic authentication requires "password"',
171	            path: ['password'],
172	          });
173	        }
174	      }
175	    }
176	  });
177	
178	const remoteAgentSchema = z
179	  .object({
180	    kind: z.literal('remote').optional().default('remote'),
181	    name: nameSchema,
182	    description: z.string().optional(),
183	    display_name: z.string().optional(),
184	    agent_card_url: z.string().url(),
185	    auth: authConfigSchema.optional(),
186	  })
187	  .strict();
188	
189	// Use a Zod union to automatically discriminate between local and remote
190	// agent types.
191	const agentUnionOptions = [
192	  { schema: localAgentSchema, label: 'Local Agent' },
193	  { schema: remoteAgentSchema, label: 'Remote Agent' },
194	] as const;
195	
196	const remoteAgentsListSchema = z.array(remoteAgentSchema);
197	
198	const markdownFrontmatterSchema = z.union([
199	  agentUnionOptions[0].schema,
200	  agentUnionOptions[1].schema,
201	]);
202	
203	function formatZodError(error: z.ZodError, context: string): string {
204	  const issues = error.issues
205	    .map((i) => {
206	      // Handle union errors specifically to give better context
207	      if (i.code === z.ZodIssueCode.invalid_union) {
208	        return i.unionErrors
209	          .map((unionError, index) => {
210	            const label =
211	              agentUnionOptions[index]?.label ?? `Agent type #${index + 1}`;
212	            const unionIssues = unionError.issues
213	              .map((u) => `${u.path.join('.')}: ${u.message}`)
214	              .join(', ');
215	            return `(${label}) ${unionIssues}`;
216	          })
217	          .join('\n');
218	      }
219	      return `${i.path.join('.')}: ${i.message}`;
220	    })
221	    .join('\n');
222	  return `${context}:\n${issues}`;
223	}
