225	/**
226	 * Parses and validates an agent Markdown file with frontmatter.
227	 *
228	 * @param filePath Path to the Markdown file.
229	 * @param content Optional pre-loaded content of the file.
230	 * @returns An array containing the single parsed agent definition.
231	 * @throws AgentLoadError if parsing or validation fails.
232	 */
233	export async function parseAgentMarkdown(
234	  filePath: string,
235	  content?: string,
236	): Promise<FrontmatterAgentDefinition[]> {
237	  let fileContent: string;
238	  if (content !== undefined) {
239	    fileContent = content;
240	  } else {
241	    try {
242	      fileContent = await fs.readFile(filePath, 'utf-8');
243	    } catch (error) {
244	      throw new AgentLoadError(
245	        filePath,
246	        `Could not read file: ${getErrorMessage(error)}`,
247	      );
248	    }
249	  }
250	
251	  // Split frontmatter and body
252	  const match = fileContent.match(FRONTMATTER_REGEX);
253	  if (!match) {
254	    throw new AgentLoadError(
255	      filePath,
256	      'Invalid agent definition: Missing mandatory YAML frontmatter. Agent Markdown files MUST start with YAML frontmatter enclosed in triple-dashes "---" (e.g., ---\nname: my-agent\n---).',
257	    );
258	  }
