78	  /**
79	   * Acknowledges and registers a previously unacknowledged agent.
80	   */
81	  async acknowledgeAgent(agent: AgentDefinition): Promise<void> {
82	    const ackService = this.config.getAcknowledgedAgentsService();
83	    const projectRoot = this.config.getProjectRoot();
84	    if (agent.metadata?.hash) {
85	      await ackService.acknowledge(
86	        projectRoot,
87	        agent.name,
88	        agent.metadata.hash,
