102	  private async loadAgents(): Promise<void> {
103	    this.agents.clear();
104	    this.allDefinitions.clear();
105	    this.loadBuiltInAgents();
106	
107	    if (!this.config.isAgentsEnabled()) {
108	      return;
109	    }
110	
111	    // Load user-level agents: ~/.gemini/agents/
112	    const userAgentsDir = Storage.getUserAgentsDir();
113	    const userAgents = await loadAgentsFromDirectory(userAgentsDir);
114	    for (const error of userAgents.errors) {
115	      debugLogger.warn(
116	        `[AgentRegistry] Error loading user agent: ${error.message}`,
117	      );
118	      coreEvents.emitFeedback('error', `Agent loading error: ${error.message}`);
119	    }
120	    await Promise.allSettled(
121	      userAgents.agents.map((agent) => this.registerAgent(agent)),
122	    );
123	
124	    // Load project-level agents: .gemini/agents/ (relative to Project Root)
125	    const folderTrustEnabled = this.config.getFolderTrust();
126	    const isTrustedFolder = this.config.isTrustedFolder();
127	
128	    if (!folderTrustEnabled || isTrustedFolder) {
129	      const projectAgentsDir = this.config.storage.getProjectAgentsDir();
130	      const projectAgents = await loadAgentsFromDirectory(projectAgentsDir);
131	      for (const error of projectAgents.errors) {
132	        coreEvents.emitFeedback(
133	          'error',
134	          `Agent loading error: ${error.message}`,
135	        );
136	      }
137	
138	      const ackService = this.config.getAcknowledgedAgentsService();
139	      const projectRoot = this.config.getProjectRoot();
140	      const unacknowledgedAgents: AgentDefinition[] = [];
141	      const agentsToRegister: AgentDefinition[] = [];
142	
143	      for (const agent of projectAgents.agents) {
144	        // If it's a remote agent, use the agentCardUrl as the hash.
145	        // This allows multiple remote agents in a single file to be tracked independently.
146	        if (agent.kind === 'remote') {
147	          if (!agent.metadata) {
148	            agent.metadata = {};
149	          }
150	          agent.metadata.hash = agent.agentCardUrl;
151	        }
152	
153	        if (!agent.metadata?.hash) {
154	          agentsToRegister.push(agent);
155	          continue;
156	        }
157	
158	        const isAcknowledged = await ackService.isAcknowledged(
159	          projectRoot,
160	          agent.name,
161	          agent.metadata.hash,
162	        );
163	
164	        if (isAcknowledged) {
165	          agentsToRegister.push(agent);
166	        } else {
167	          unacknowledgedAgents.push(agent);
168	        }
169	      }
170	
171	      if (unacknowledgedAgents.length > 0) {
172	        coreEvents.emitAgentsDiscovered(unacknowledgedAgents);
173	      }
174	
175	      await Promise.allSettled(
176	        agentsToRegister.map((agent) => this.registerAgent(agent)),
177	      );
178	    } else {
179	      coreEvents.emitFeedback(
180	        'info',
181	        'Skipping project agents due to untrusted folder. To enable, ensure that the project root is trusted.',
182	      );
183	    }
184	
185	    // Load agents from extensions
186	    for (const extension of this.config.getExtensions()) {
187	      if (extension.isActive && extension.agents) {
188	        await Promise.allSettled(
189	          extension.agents.map((agent) => this.registerAgent(agent)),
190	        );
191	      }
192	    }
193	
194	    if (this.config.getDebugMode()) {
195	      debugLogger.log(
196	        `[AgentRegistry] Loaded with ${this.agents.size} agents.`,
197	      );
198	    }
199	  }
