28	/**
29	 * Authentication handler implementation using Google Application Default Credentials (ADC).
30	 */
31	export class ADCHandler implements AuthenticationHandler {
32	  private auth = new GoogleAuth({
33	    scopes: ['https://www.googleapis.com/auth/cloud-platform'],
34	  });
35	
36	  async headers(): Promise<Record<string, string>> {
37	    try {
38	      const client = await this.auth.getClient();
39	      const token = await client.getAccessToken();
40	      if (token.token) {
41	        return { Authorization: `Bearer ${token.token}` };
42	      }
43	      throw new Error('Failed to retrieve ADC access token.');
44	    } catch (e) {
45	      const errorMessage = `Failed to get ADC token: ${
46	        e instanceof Error ? e.message : String(e)
47	      }`;
48	      debugLogger.log('ERROR', errorMessage);
49	      throw new Error(errorMessage);
50	    }
51	  }
52	
53	  async shouldRetryWithHeaders(
54	    _response: unknown,
55	  ): Promise<Record<string, string> | undefined> {
56	    // For ADC, we usually just re-fetch the token if needed.
57	    return this.headers();
58	  }
59	}
