61	/**
62	 * A tool invocation that proxies to a remote A2A agent.
63	 *
64	 * This implementation bypasses the local `LocalAgentExecutor` loop and directly
65	 * invokes the configured A2A tool.
66	 */
67	export class RemoteAgentInvocation extends BaseToolInvocation<
68	  RemoteAgentInputs,
69	  ToolResult
70	> {
71	  // Persist state across ephemeral invocation instances.
72	  private static readonly sessionState = new Map<
73	    string,
74	    { contextId?: string; taskId?: string }
75	  >();
76	  // State for the ongoing conversation with the remote agent
77	  private contextId: string | undefined;
78	  private taskId: string | undefined;
79	  // TODO: See if we can reuse the singleton from AppContainer or similar, but for now use getInstance directly
80	  // as per the current pattern in the codebase.
81	  private readonly clientManager = A2AClientManager.getInstance();
82	  private readonly authHandler = new ADCHandler();
83	
84	  constructor(
85	    private readonly definition: RemoteAgentDefinition,
86	    params: AgentInputs,
87	    messageBus: MessageBus,
88	    _toolName?: string,
89	    _toolDisplayName?: string,
90	  ) {
91	    const query = params['query'] ?? DEFAULT_QUERY_STRING;
92	    if (typeof query !== 'string') {
93	      throw new Error(
94	        `Remote agent '${definition.name}' requires a string 'query' input.`,
95	      );
96	    }
97	    // Safe to pass strict object to super
98	    super(
99	      { query },
100	      messageBus,
101	      _toolName ?? definition.name,
102	      _toolDisplayName ?? definition.displayName,
103	    );
104	  }
105	
106	  getDescription(): string {
107	    return `Calling remote agent ${this.definition.displayName ?? this.definition.name}`;
108	  }
109	
110	  protected override async getConfirmationDetails(
111	    _abortSignal: AbortSignal,
112	  ): Promise<ToolCallConfirmationDetails | false> {
113	    // For now, always require confirmation for remote agents until we have a policy system for them.
114	    return {
115	      type: 'info',
116	      title: `Call Remote Agent: ${this.definition.displayName ?? this.definition.name}`,
117	      prompt: `Calling remote agent: "${this.params.query}"`,
118	      onConfirm: async (_outcome: ToolConfirmationOutcome) => {
119	        // Policy updates are now handled centrally by the scheduler
120	      },
121	    };
122	  }
123	
124	  async execute(
125	    _signal: AbortSignal,
126	    updateOutput?: (output: string | AnsiOutput) => void,
127	  ): Promise<ToolResult> {
128	    // 1. Ensure the agent is loaded (cached by manager)
129	    // We assume the user has provided an access token via some mechanism (TODO),
130	    // or we rely on ADC.
131	    const reassembler = new A2AResultReassembler();
132	    try {
133	      const priorState = RemoteAgentInvocation.sessionState.get(
134	        this.definition.name,
135	      );
136	      if (priorState) {
137	        this.contextId = priorState.contextId;
138	        this.taskId = priorState.taskId;
139	      }
140	
141	      if (!this.clientManager.getClient(this.definition.name)) {
142	        await this.clientManager.loadAgent(
143	          this.definition.name,
144	          this.definition.agentCardUrl,
145	          this.authHandler,
146	        );
147	      }
148	
149	      const message = this.params.query;
150	
151	      const stream = this.clientManager.sendMessageStream(
152	        this.definition.name,
153	        message,
154	        {
155	          contextId: this.contextId,
156	          taskId: this.taskId,
157	          signal: _signal,
158	        },
159	      );
160	
161	      let finalResponse: SendMessageResult | undefined;
162	
163	      for await (const chunk of stream) {
164	        if (_signal.aborted) {
165	          throw new Error('Operation aborted');
166	        }
167	        finalResponse = chunk;
168	        reassembler.update(chunk);
169	
170	        if (updateOutput) {
171	          updateOutput(reassembler.toString());
172	        }
173	
174	        const {
175	          contextId: newContextId,
176	          taskId: newTaskId,
177	          clearTaskId,
178	        } = extractIdsFromResponse(chunk);
179	
180	        if (newContextId) {
181	          this.contextId = newContextId;
182	        }
183	
184	        this.taskId = clearTaskId ? undefined : (newTaskId ?? this.taskId);
185	      }
186	
187	      if (!finalResponse) {
188	        throw new Error('No response from remote agent.');
189	      }
190	
191	      const finalOutput = reassembler.toString();
192	
193	      debugLogger.debug(
194	        `[RemoteAgent] Final response from ${this.definition.name}:\n${JSON.stringify(finalResponse, null, 2)}`,
195	      );
196	
197	      return {
198	        llmContent: [{ text: finalOutput }],
199	        returnDisplay: finalOutput,
200	      };
201	    } catch (error: unknown) {
202	      const partialOutput = reassembler.toString();
203	      const errorMessage = `Error calling remote agent: ${error instanceof Error ? error.message : String(error)}`;
204	      const fullDisplay = partialOutput
205	        ? `${partialOutput}\n\n${errorMessage}`
206	        : errorMessage;
207	      return {
208	        llmContent: [{ text: fullDisplay }],
209	        returnDisplay: fullDisplay,
210	        error: { message: errorMessage },
211	      };
212	    } finally {
213	      // Persist state even on partial failures or aborts to maintain conversational continuity.
214	      RemoteAgentInvocation.sessionState.set(this.definition.name, {
215	        contextId: this.contextId,
216	        taskId: this.taskId,
217	      });
218	    }
219	  }
220	}
