export class HttpAuthProvider extends BaseA2AAuthProvider {
  readonly type = 'http' as const;

  private resolvedToken: string | undefined;
  private resolvedUsername: string | undefined;
  private resolvedPassword: string | undefined;
  private resolvedValue: string | undefined;

  constructor(private readonly config: HttpAuthConfig) {
    super();
  }

  override async initialize(): Promise<void> {
    const config = this.config;
    if ('token' in config) {
      this.resolvedToken = await HttpAuthProvider.resolve(config.token);
    } else if ('username' in config) {
      this.resolvedUsername = await HttpAuthProvider.resolve(config.username);
      this.resolvedPassword = await HttpAuthProvider.resolve(config.password);
    } else {
      this.resolvedValue = await HttpAuthProvider.resolve(config.value);
    }
